head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[tabControl > E > ontabclick]<br/>Tab 버튼 영역을 마우스로 클릭할 때 발생합니다.",
    "validation" : [
        "Tab 페이지가 비활성화(disabled) 상태일때도 Tab 버튼 영역 클릭 시 onbeforeselect -> ontabclick 순서로 이벤트가 발생합니다.",        
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정   
    let properties = {
        disabled : true,
    };

    let cList = $c.gcm.createCList(properties);      
    let eList = $c.gcm.createEList(["onbeforeselect", "ontabclick"]);

    let grp_comp = $c.gcm.getTestGroup();    
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:tabControl ' + strNameSpace + ' ' + eList + ' id="" style="width:500px;height:200px;">';
    strTarget += '<w2:tabs style="height:40px;" id="tabs1" label="Tabs1"></w2:tabs>';
    strTarget += '<w2:tabs ' + cList + ' style="height:40px;" id="tabs2" label="Tabs2"></w2:tabs>';
    strTarget += '<w2:tabs ' + cList + ' style="height:40px;" id="tabs3" label="Tabs3"></w2:tabs>';
    strTarget += '<w2:content alwaysDraw="false" style="height:160px;" id="content1">';
    strTarget += '<w2:button style="width:80px; width:130px; height:50px;" id="content1_child" label="content1_child"></w2:button>';
    strTarget += '</w2:content>';
    strTarget += '<w2:content alwaysDraw="false" style="height:160px" id="content2">';
    strTarget += '<xf:input id="content2_child" style="width:144px; height:21px; " initValue="content2_child"></xf:input>';
    strTarget += '</w2:content>';
    strTarget += '<w2:content alwaysDraw="false" style="height:160px" id="content3">';    
    strTarget += '<w2:textbox id="content3_child" label="content3_child" style="width:200px; height:50px; background-color:var(--ws-gray-300);"></w2:textbox>';
    strTarget += '</w2:content>';
    strTarget += '</w2:tabControl>';

    // target 생성
    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "tabControl",
        strTarget,
        grp_comp
    );   
}



scwin.target1_onbeforeselect = function (selectedIndex, index) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onbeforeselect=====");
}



scwin.target1_ontabclick = function (tabId, index) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_ontabclick=====");
}
